    fun has(name: String): Boolean = paths.containsKey(name)

    fun drawable(name: String, color: Int): Drawable {
        val raw = paths[name] ?: paths["circle-question"]!!
        val bar = raw.indexOf('|')
        val dims = raw.substring(0, bar).split(' ')
        val path = cache.getOrPut(name) { PathParser.createPathFromPathData(raw.substring(bar + 1)) }
        return FillIcon(path, dims[0].toFloat(), dims[1].toFloat(), color)
    }

    fun view(ctx: Context, name: String, color: Int): ImageView {
        val v = ImageView(ctx)
        v.setImageDrawable(drawable(name, color))
        return v
    }
}

class FillIcon(private val path: Path, private val vw: Float, private val vh: Float, color: Int) : Drawable() {
    private val paint = Paint(Paint.ANTI_ALIAS_FLAG)

    init {
        paint.style = Paint.Style.FILL
        paint.color = color
    }

    override fun draw(canvas: Canvas) {
        val b = bounds
        if (b.width() <= 0 || b.height() <= 0) return
        val s = Math.min(b.width() / vw, b.height() / vh)
        canvas.save()
        canvas.translate(b.left + (b.width() - vw * s) / 2f, b.top + (b.height() - vh * s) / 2f)
        canvas.scale(s, s)
        canvas.drawPath(path, paint)
        canvas.restore()
    }

    fun tint(color: Int) {
        paint.color = color
        invalidateSelf()
    }

    override fun setAlpha(alpha: Int) {
        paint.alpha = alpha
        invalidateSelf()
    }

    override fun setColorFilter(cf: ColorFilter?) {
        paint.colorFilter = cf
        invalidateSelf()
    }

    @Deprecated("Deprecated in Java")
    override fun getOpacity(): Int = PixelFormat.TRANSLUCENT
}
